diff --git a/crates/ignore/src/walk.rs b/crates/ignore/src/walk.rs
index f04f53a..3de3f7f 100644
--- a/crates/ignore/src/walk.rs
+++ b/crates/ignore/src/walk.rs
@@ -2360,6 +2360,78 @@ mod tests {
         );
     }

+    #[test]
+    fn git_exclude_linked_worktree() {
+        let td = tmpdir();
+        let git_dir = td.path().join("repo/.git");
+        let worktree_git_dir = git_dir.join("worktrees/linked");
+        let worktree = td.path().join("linked");
+        mkdirp(git_dir.join("info"));
+        mkdirp(&worktree_git_dir);
+        mkdirp(worktree.join("sub"));
+        wfile(git_dir.join("info/exclude"), "ignored\n/anchored\n");
+        wfile(
+            worktree.join(".git"),
+            &format!("gitdir: {}\n", worktree_git_dir.display()),
+        );
+        for name in
+            ["ignored", "anchored", "kept", "sub/ignored", "sub/anchored"]
+        {
+            wfile(worktree.join(name), "");
+        }
+
+        for commondir in ["../..", git_dir.to_str().unwrap()] {
+            wfile(worktree_git_dir.join("commondir"), commondir);
+            for require_git in [true, false] {
+                let mut builder = WalkBuilder::new(&worktree);
+                builder
+                    .parents(false)
+                    .git_global(false)
+                    .git_ignore(false)
+                    .require_git(require_git);
+                assert_paths(
+                    &worktree,
+                    &builder,
+                    &["kept", "sub", "sub/anchored"],
+                );
+
+                builder.git_exclude(false);
+                assert_paths(
+                    &worktree,
+                    &builder,
+                    &[
+                        "ignored",
+                        "anchored",
+                        "kept",
+                        "sub",
+                        "sub/ignored",
+                        "sub/anchored",
+                    ],
+                );
+            }
+        }
+    }
+
+    #[test]
+    fn git_exclude_without_require_git() {
+        let td = tmpdir();
+        wfile(td.path().join(".gitignore"), "from_gitignore\n");
+        wfile(td.path().join("from_gitignore"), "");
+        wfile(td.path().join("from_exclude"), "");
+        wfile(td.path().join("kept"), "");
+        let mut builder = WalkBuilder::new(td.path());
+        builder.parents(false).git_global(false).require_git(false);
+
+        assert_paths(td.path(), &builder, &["from_exclude", "kept"]);
+
+        mkdirp(td.path().join(".git/info"));
+        wfile(td.path().join(".git/info/exclude"), "from_exclude\n");
+        assert_paths(td.path(), &builder, &["kept"]);
+
+        builder.git_exclude(false);
+        assert_paths(td.path(), &builder, &["from_exclude", "kept"]);
+    }
+
     #[test]
     fn explicit_ignore() {
         let td = tmpdir();

