+/** Tests FIFO acquisition independently of timer scheduling. */
+class TimedSemaphoreFairnessTest {
+
+    private static final class Waiter extends Thread {
+        private final TimedSemaphore semaphore;
+        private Throwable failure;
+        private boolean acquired;
+
+        Waiter(final TimedSemaphore semaphore) {
+            this.semaphore = semaphore;
+            setDaemon(true);
+        }
+
+        @Override
+        public void run() {
+            try {
+                semaphore.acquire();
+                acquired = true;
+            } catch (final InterruptedException | IllegalStateException ex) {
+                failure = ex;
+            }
+        }
+
+        void awaitDone() throws InterruptedException {
+            join(5000);
+            assertFalse(isAlive(), "Acquire call did not finish");
+        }
+
+        void awaitSuccess() throws InterruptedException {
+            awaitDone();
+            assertNull(failure);
+            assertTrue(acquired);
+        }
+    }
+
+    private static final class Fixture implements AutoCloseable {
+        private final ScheduledThreadPoolExecutor service = new ScheduledThreadPoolExecutor(1);
+        private final TimedSemaphore semaphore;
+        private final List<Waiter> waiters = new ArrayList<>();
+
+        Fixture(final boolean fair) {
+            semaphore = TimedSemaphore.builder().setPeriod(1).setTimeUnit(TimeUnit.DAYS).setLimit(1)
+                    .setService(service).setFair(fair).get();
+        }
+
+        Waiter enqueue() throws InterruptedException {
+            final Waiter waiter = new Waiter(semaphore);
+            waiters.add(waiter);
+            waiter.start();
+            final long deadline = System.nanoTime() + Duration.ofSeconds(5).toNanos();
+            while (waiter.getState() != Thread.State.WAITING && waiter.isAlive() && System.nanoTime() < deadline) {
+                Thread.sleep(1);
+            }
+            assertEquals(Thread.State.WAITING, waiter.getState(), "Acquire call did not block");
+            return waiter;
+        }
+
+        @Override
+        public void close() throws InterruptedException {
+            semaphore.shutdown();
+            service.shutdownNow();
+            for (final Waiter waiter : waiters) {
+                waiter.interrupt();
+                waiter.awaitDone();
+            }
+        }
+    }
