+        final TimedSemaphore.Builder builder = TimedSemaphore.builder().setPeriod(2).setTimeUnit(TimeUnit.MINUTES).setLimit(3);
+        final TimedSemaphore defaultSemaphore = builder.get();
+        final TimedSemaphore fairSemaphore = builder.setFair(true).get();
+        final TimedSemaphore legacy = new TimedSemaphore(2, TimeUnit.MINUTES, 3);
+        try {
+            assertFalse(defaultSemaphore.isFair());
+            assertFalse(legacy.isFair());
+            assertTrue(fairSemaphore.isFair());
+            assertEquals(2, fairSemaphore.getPeriod());
+            assertEquals(TimeUnit.MINUTES, fairSemaphore.getUnit());
+            assertEquals(3, fairSemaphore.getLimit());
+        } finally {
+            defaultSemaphore.shutdown();
+            fairSemaphore.shutdown();
