+    }
+
+    @Test
+    void testFifoAcrossPeriodsAndAccounting() throws InterruptedException {
+        try (Fixture fixture = new Fixture(true)) {
+            final TimedSemaphore semaphore = fixture.semaphore;
+            semaphore.acquire();
+            final List<Waiter> ordered = new ArrayList<>();
+            for (int i = 0; i < 4; i++) {
+                ordered.add(fixture.enqueue());
+            }
+            // Notifications alone must not allow a waiter to consume a permit.
+            synchronized (semaphore) {
+                semaphore.notifyAll();
+                assertEquals(1, semaphore.getAcquireCount());
+                assertFalse(semaphore.tryAcquire());
+            }
+            for (int i = 0; i < ordered.size(); i++) {
+                semaphore.endOfPeriod();
+                ordered.get(i).awaitSuccess();
+                assertEquals(1, semaphore.getAcquireCount());
+                assertEquals(0, semaphore.getAvailablePermits());
