+                    assertTrue(ordered.get(j).isAlive(), "A later caller overtook the queue head");
+                }
+                if (i == 0) {
+                    // A caller arriving after the first period must join the tail.
+                    ordered.add(fixture.enqueue());
+                }
+            }
+        }
+    }
+
+    @Test
+    void testInterruptedHeadAndMiddleDoNotConsumePermits() throws InterruptedException {
+        try (Fixture fixture = new Fixture(true)) {
+            final TimedSemaphore semaphore = fixture.semaphore;
+            semaphore.acquire();
+            final Waiter head = fixture.enqueue();
+            final Waiter next = fixture.enqueue();
+            final Waiter middle = fixture.enqueue();
+            final Waiter tail = fixture.enqueue();
+            middle.interrupt();
+            middle.awaitDone();
+            assertInstanceOf(InterruptedException.class, middle.failure);
