+            this.order = order;
+            this.id = id;
+            setDaemon(true);
+        }
+
+        @Override
+        public void run() {
+            try {
+                synchronized (semaphore) {
+                    beforeAcquire.run();
+                    semaphore.acquire();
+                    order.add(id);
+                }
+            } catch (final Throwable ex) {
