+        } else {
+            assertTrue(failureType.isInstance(thread.failure));
+        }
+    }
+
+    private static Acquirer enqueue(final TimedSemaphore semaphore, final List<Integer> order, final int id) throws InterruptedException {
+        final Acquirer thread = new Acquirer(semaphore, order, id);
+        thread.start();
+        awaitWaiting(thread);
+        return thread;
+    }
